const API='/api/v1';
const state={bootstrap:null,overview:null,debts:[],route:'overview',recurringMonth:new Date().toISOString().slice(0,7),recurringRows:[],imports:[],allCards:[],preferences:null,forecast:null,scenario:null,copilotStatus:null,copilotSessions:[],copilotSession:null,copilotBusy:false,accounts:[],goals:[],planning:null,uiPreferences:{theme:'system',dashboardMode:'standard',dashboardWidgets:['netWorth','debt','cashflow','emergency','credit','alerts','goals']},customizing:false,legacyReport:null};
const $=s=>document.querySelector(s);
const money=new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0});
const money2=new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',minimumFractionDigits:2,maximumFractionDigits:2});
const dateFmt=new Intl.DateTimeFormat('es-MX',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toISOString().slice(0,10);
function fmtDate(s){return s?dateFmt.format(new Date(s+'T00:00:00Z')):'—'}
function pct(v){return `${Number(v||0).toFixed(1)}%`}
async function api(path,opts={}){const headers={...(opts.headers||{})};if(opts.body&&!(opts.body instanceof Blob)&&!(opts.body instanceof ArrayBuffer)&&!headers['content-type'])headers['content-type']='application/json';const r=await fetch(API+path,{...opts,headers,credentials:'same-origin'});if(r.status===401){location.href='/login.html';throw new Error('Sesión requerida')}const type=r.headers.get('content-type')||'';let x;if(type.includes('application/json'))x=await r.json();else{x={error:{message:(await r.text())||`HTTP ${r.status}`}}}if(!r.ok)throw new Error(x?.error?.message||'Error de API');return x}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),3000)}
function cardMap(){return new Map((state.allCards.length?state.allCards:state.bootstrap.cards).map(c=>[c.id,c]))}
function snapshotMap(){return new Map(state.bootstrap.snapshots.map(s=>[s.cardId,s]))}
function liveBalance(s,cardId=s?.cardId){const delta=state.bootstrap.transactions.filter(t=>t.cardId===cardId&&t.date<=today()&&(!s?.statementDate||t.date>s.statementDate)).reduce((sum,t)=>sum+((t.kind==='payment'||t.kind==='refund')?-t.amount:t.amount),0);return Math.max(0,(s?.totalBalance||0)+delta)}
function monthlyEquivalent(r){let gross=r.amount;if(r.frequency==='bimonthly')gross/=2;if(r.frequency==='every_n_days')gross=r.amount*30/(r.everyNDays||30);if(r.frequency==='one_time')gross=0;return gross-(r.offsetIncome||0)}
function frequencyText(r){if(r.frequency==='monthly')return 'Mensual';if(r.frequency==='bimonthly')return 'Bimestral';if(r.frequency==='every_n_days')return `Cada ${r.everyNDays} días`;return 'Una vez'}
function metric(label,value,meta,klass=''){return `<article class="metric"><div class="label">${esc(label)}</div><div class="value">${value}</div><div class="meta ${klass}">${esc(meta)}</div></article>`}
const WIDGET_PRESETS={simple:['netWorth','debt','cashflow','alerts'],standard:['netWorth','debt','cashflow','emergency','credit','alerts','goals'],analytical:['netWorth','debt','cashflow','emergency','credit','alerts','goals','system']};
function widgetEnabled(id){const list=state.uiPreferences?.dashboardWidgets||WIDGET_PRESETS.standard;return list.includes(id)}
function resolvedTheme(pref=state.uiPreferences?.theme||'system'){return pref==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):pref}
function applyTheme(pref=state.uiPreferences?.theme||'system'){const r=resolvedTheme(pref);document.documentElement.dataset.theme=r;const meta=$('#themeColorMeta');if(meta)meta.content=r==='dark'?'#0b1220':'#315efb';const b=$('#themeToggle');if(b){b.textContent=pref==='system'?'◐':r==='dark'?'☀':'☾';b.title=`Tema: ${pref}`}}
function updateMobileNav(){document.querySelectorAll('[data-mobile-route]').forEach(b=>b.classList.toggle('active',b.dataset.mobileRoute===state.route||(b.dataset.mobileRoute==='more'&&!['overview','cashflow','transactions','goals'].includes(state.route))))}
function alertHtml(a){return `<div class="alert-item ${esc(a.severity)}" data-alert-route="${esc(a.route||'')}"><span class="alert-dot"></span><div class="alert-copy"><strong>${esc(a.title)}</strong><span>${esc(a.message)}</span></div></div>`}
function updateAlertsChrome(){const alerts=state.planning?.alerts||[];const important=alerts.filter(a=>a.severity==='critical'||a.severity==='warning').length;const badge=$('#alertsBadge');if(badge){badge.hidden=!important;badge.textContent=String(important)}const pop=$('#alertsPopover');if(pop)pop.innerHTML=`<div class="alert-popover-head"><strong>Alertas financieras</strong><span>${alerts.length} señales</span></div>${alerts.map(alertHtml).join('')||'<div class="empty compact">Sin alertas.</div>'}`}
function accountTypeLabel(t){return ({checking:'Cuenta corriente',savings:'Ahorro',cash:'Efectivo',investment:'Inversión',other:'Otra'})[t]||t}
function accountIcon(t){return ({checking:'BA',savings:'AH',cash:'EF',investment:'IN',other:'OT'})[t]||'AC'}
function goalTypeLabel(t){return ({emergency_fund:'Fondo de emergencia',purchase:'Compra',travel:'Viaje',annual_expense:'Gasto anual',other:'Otra'})[t]||t}

async function refresh(){
  [state.bootstrap,state.overview,state.debts,state.allCards,state.preferences,state.accounts,state.goals,state.planning,state.uiPreferences]=await Promise.all([api('/bootstrap'),api('/overview?asOf='+today()),api('/debt-plans'),api('/cards?includeArchived=true'),api('/preferences'),api('/accounts?includeArchived=true'),api('/goals?includeArchived=true'),api('/planning-summary?asOf='+today()),api('/ui-preferences')]);
  state.forecast=null;applyTheme();updateAlertsChrome();$('#asOfLabel').textContent=fmtDate(state.overview.asOf);updateMobileNav();
}
async function load(){await refresh();await render();if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})}

function setRoute(route){state.route=route;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route===route));$('#sidebar').classList.remove('open');$('#sidebarBackdrop')?.classList.remove('show');const titles={overview:'Overview',accounts:'Cuentas y activos',goals:'Metas',cards:'Tarjetas',transactions:'Movimientos',debt:'Deuda',recurring:'Gastos recurrentes',imports:'Estados y conciliación',cashflow:'Cash flow',simulator:'Simulador financiero',budgets:'Presupuestos',copilot:'Copiloto financiero',reports:'Reportes'};$('#pageTitle').textContent=titles[route]||route;updateMobileNav();render()}

function renderOverview(){
  const o=state.overview,p=state.planning||{},snaps=state.bootstrap.snapshots,cards=cardMap();const fixedPct=o.monthlyFixedNet/o.monthlyIncome*100;const activeSnaps=state.bootstrap.cards.map(c=>snaps.find(s=>s.cardId===c.id)||{cardId:c.id,totalBalance:0,dataQuality:'estimated'});const mode=state.uiPreferences?.dashboardMode||'standard';const months=state.forecast?.forecast?.monthly?.slice(0,4)||[];
  const metrics=[];
  if(widgetEnabled('netWorth'))metrics.push(metric(p.accountsConfigured?'Patrimonio neto':'Patrimonio neto',''+(p.accountsConfigured?money.format(p.netWorth):'—'),p.accountsConfigured?`${money.format(p.totalAssets)} en activos`:'Agrega cuentas para completar el balance',p.accountsConfigured?(p.netWorth>=0?'good':'warn'):''));
  if(widgetEnabled('debt'))metrics.push(metric('Deuda total',money.format(o.totalDebt),`${o.creditUtilization.toFixed(1)}% de tus líneas`,'warn'));
  metrics.push(metric('Flujo antes de variable',money.format(o.monthlyFreeBeforeVariableAndInstallments),'Antes de MSI y gasto discrecional','good'));
  if(p.accountsConfigured)metrics.push(metric('Liquidez registrada',money.format(p.liquidAssets),'Cuentas corrientes, ahorro y efectivo'));
  else metrics.push(metric('Gasto fijo neto',money.format(o.monthlyFixedNet),`${fixedPct.toFixed(1)}% de tu ingreso mensual`));
  const panels=[];
  if(widgetEnabled('alerts'))panels.push(`<section class="panel"><div class="panel-head"><div><h2>Centro de alertas</h2><span>Señales deterministas, no opiniones de IA</span></div><span>${p.alerts?.length||0}</span></div><div class="panel-body">${(p.alerts||[]).slice(0,5).map(alertHtml).join('')}</div></section>`);
  if(widgetEnabled('credit'))panels.push(`<section class="panel"><div class="panel-head"><div><h2>Portafolio de crédito</h2><span>Saldo oficial + movimientos nuevos</span></div><span>${money.format(o.totalCreditLimit)} línea total</span></div><div class="panel-body"><div class="portfolio">${activeSnaps.map(s=>{const c=cards.get(s.cardId);if(!c)return'';const bal=liveBalance(s),u=bal/c.creditLimit*100,cls=u>=90?'critical':u>=70?'high':'';return `<div class="mini-card" data-card-open="${c.id}"><div class="mini-row"><div><div class="bank">${esc(c.issuer)}</div><div class="card-name">${esc(c.name)}</div></div><span class="quality ${s.dataQuality}">${s.dataQuality}</span></div><div class="mini-row" style="margin-top:12px"><span class="muted">Saldo</span><strong class="amount">${money.format(bal)}</strong></div><div class="progress ${cls}"><i style="width:${Math.min(100,u)}%"></i></div><div class="mini-row"><span class="muted">Utilización ${u.toFixed(1)}%</span><span class="muted">Límite ${money.format(c.creditLimit)}</span></div></div>`}).join('')}</div></div></section>`);
  if(widgetEnabled('cashflow'))panels.push(`<section class="panel"><div class="panel-head"><div><h2>Próximos meses</h2><span>Saldo de cierre proyectado</span></div><button class="secondary small" data-route-jump="cashflow">Ver detalle</button></div><div class="panel-body"><div class="mini-forecast">${months.length?months.map(x=>`<div><span>${esc(x.month)}</span><strong class="${x.endingBalance<0?'negative':'positive'}">${money.format(x.endingBalance)}</strong><small>neto ${money.format(x.net)}</small></div>`).join(''):'<div class="empty compact">Cargando forecast…</div>'}</div></div></section>`);
  if(widgetEnabled('emergency')){const e=p.emergencyFund||{targetAmount:0,currentAmount:0,gap:0,coverageMonths:0};const ep=e.targetAmount?Math.min(100,e.currentAmount/e.targetAmount*100):0;panels.push(`<section class="panel"><div class="panel-head"><div><h2>Fondo de emergencia</h2><span>${e.source==='accounts'?'Saldo tomado de cuentas marcadas':'Saldo tomado de preferencias'}</span></div><button class="secondary small" data-route-jump="goals">Metas</button></div><div class="panel-body"><div class="goal-amounts"><strong>${money.format(e.currentAmount)}</strong><span>meta ${money.format(e.targetAmount)}</span></div><div class="progress"><i style="width:${ep}%"></i></div><div class="goal-meta"><span>${ep.toFixed(0)}% fondeado</span><span>${e.coverageMonths.toFixed(1)} meses</span></div></div></section>`)}
  if(widgetEnabled('goals')){const goals=p.goals?.items||[];panels.push(`<section class="panel"><div class="panel-head"><div><h2>Metas activas</h2><span>${p.goals?.activeCount||0} en progreso</span></div><button class="secondary small" data-route-jump="goals">Administrar</button></div><div class="panel-body">${goals.length?goals.slice(0,3).map(g=>`<div class="goal-progress"><div class="goal-amounts"><strong>${esc(g.goal.name)}</strong><span>${g.fundedPct.toFixed(0)}%</span></div><div class="progress"><i style="width:${g.fundedPct}%"></i></div><div class="goal-meta"><span>${money.format(g.goal.currentAmount)}</span><span>${money.format(g.goal.targetAmount)}</span></div></div>`).join(''):'<div class="empty-action"><strong>Aún no hay metas</strong><span>Crea un fondo de emergencia, viaje, compra o gasto anual.</span><button class="primary small" data-route-jump="goals">Crear meta</button></div>'}</div></section>`)}
  if(widgetEnabled('system')||mode==='analytical')panels.push(`<section class="panel"><div class="panel-head"><div><h2>Sistema de datos</h2><span>v0.8</span></div></div><div class="panel-body"><div class="detail-grid"><div class="detail-kpi"><span>Tarjetas activas</span><strong>${state.bootstrap.cards.length}</strong></div><div class="detail-kpi"><span>Cuentas</span><strong>${state.accounts.filter(a=>a.status!=='archived').length}</strong></div><div class="detail-kpi"><span>Movimientos</span><strong>${state.bootstrap.transactions.length}</strong></div><div class="detail-kpi"><span>Recurrentes</span><strong>${state.bootstrap.recurring.length}</strong></div></div></div></section>`);
  return `<div class="dashboard-tools"><button class="secondary small" id="customizeDashboard">Personalizar dashboard</button></div>${state.customizing?renderDashboardCustomizer():''}<div class="hero-grid">${metrics.join('')}</div><div class="section-stack">${panels.map((x,i)=>i%2===0&&panels[i+1]?`<div class="grid-2">${x}${panels[i+1]}</div>`:i%2===0?x:'').join('')}</div>`;
}

function renderDashboardCustomizer(){const prefs=state.uiPreferences||{};const labels={netWorth:'Patrimonio neto',debt:'Deuda',cashflow:'Cash flow',emergency:'Fondo de emergencia',credit:'Crédito',alerts:'Alertas',goals:'Metas',system:'Sistema de datos'};return `<section class="panel personalizer"><div class="panel-head"><div><h2>Personalización</h2><span>Se guarda en tu estado privado de la nube</span></div></div><div class="panel-body"><div class="preset-row">${['simple','standard','analytical'].map(m=>`<button class="preset-chip ${prefs.dashboardMode===m?'active':''}" data-dashboard-preset="${m}">${m==='simple'?'Simple':m==='standard'?'Normal':'Analítico'}</button>`).join('')}</div><div class="personalizer-grid">${Object.entries(labels).map(([id,label])=>`<label class="personalizer-option"><input type="checkbox" data-widget="${id}" ${widgetEnabled(id)?'checked':''}>${label}</label>`).join('')}</div><div class="personalizer-actions"><button class="secondary" id="cancelCustomize">Cerrar</button><button class="primary" id="saveCustomize">Guardar vista</button></div></div></section>`}

function renderAccounts(){const active=state.accounts.filter(a=>a.status!=='archived'),archived=state.accounts.filter(a=>a.status==='archived'),p=state.planning||{};return `<div class="hero-grid">${metric('Activos registrados',money.format(p.totalAssets||0),`${active.length} cuentas activas`)}${metric('Liquidez',money.format(p.liquidAssets||0),'Corriente + ahorro + efectivo')}${metric('Deuda',money.format(p.totalDebt||0),'Tarjetas registradas','warn')}${metric('Patrimonio neto',active.length?money.format(p.netWorth||0):'—',active.length?'Activos menos deuda':'Agrega una cuenta para calcularlo',active.length&&p.netWorth>=0?'good':'')}</div><div class="section-title"><div><h2>Cuentas y activos</h2><p>Registra saldos de banco, ahorro, efectivo o inversión. No guardamos números de cuenta.</p></div><button class="primary" id="newAccountBtn">+ Cuenta</button></div><div class="asset-grid">${active.length?active.map(a=>`<article class="asset-card"><div class="asset-head"><div><div class="asset-kind">${esc(accountTypeLabel(a.type))}</div><h3>${esc(a.name)}</h3><div class="muted">${esc(a.institution||'Sin institución')}</div></div><div class="account-icon">${accountIcon(a.type)}</div></div><div class="asset-balance">${money.format(a.balance)}</div><div class="asset-meta"><span>${a.includeInNetWorth?'Incluida en patrimonio':'Excluida del patrimonio'}</span><span>${a.isEmergencyFund?'Fondo emergencia':''}</span></div><div class="asset-actions"><button class="secondary small" data-account-balance="${a.id}">Actualizar saldo</button><button class="secondary small danger-text" data-account-archive="${a.id}">Archivar</button></div></article>`).join(''):'<section class="panel" style="grid-column:1/-1"><div class="empty-action"><strong>Agrega tus activos</strong><span>Con una cuenta bancaria o de ahorro podremos calcular patrimonio neto y liquidez real.</span><button class="primary" id="emptyNewAccount">+ Primera cuenta</button></div></section>'}</div><div id="accountEditor"></div>${archived.length?`<section class="panel detail"><div class="panel-head"><div><h2>Archivadas</h2><span>${archived.length} cuentas fuera del balance diario</span></div></div><div class="panel-body">${archived.map(a=>`<div class="archive-row"><div><strong>${esc(a.name)}</strong><span>${money.format(a.balance)}</span></div></div>`).join('')}</div></section>`:''}`}
function accountForm(){return `<section class="panel detail"><div class="panel-head"><div><h2>Nueva cuenta</h2><span>Sólo nombre, tipo y saldo; nunca guardes credenciales bancarias.</span></div></div><div class="panel-body"><form id="accountForm" class="form-grid"><div class="field"><label>Nombre</label><input id="accName" placeholder="Ej. BBVA Nómina" required></div><div class="field"><label>Institución</label><input id="accInstitution" placeholder="BBVA, Banamex, efectivo..."></div><div class="field"><label>Tipo</label><select id="accType"><option value="checking">Cuenta corriente</option><option value="savings">Ahorro</option><option value="cash">Efectivo</option><option value="investment">Inversión</option><option value="other">Otra</option></select></div><div class="field"><label>Saldo actual</label><input id="accBalance" type="number" min="0" step="0.01" required></div><label class="personalizer-option"><input id="accNetWorth" type="checkbox" checked>Incluir en patrimonio neto</label><label class="personalizer-option"><input id="accEmergency" type="checkbox">Cuenta del fondo de emergencia</label><div class="form-actions"><button class="secondary" type="button" id="cancelAccount">Cancelar</button><button class="primary">Guardar cuenta</button></div></form></div></section>`}

function renderGoals(){const items=state.planning?.goals?.items||[],active=items.filter(x=>x.goal.status!=='archived');return `<div class="hero-grid">${metric('Metas activas',String(state.planning?.goals?.activeCount||0),`${money.format(state.planning?.goals?.totalGap||0)} pendientes`)}${metric('Ahorrado en metas',money.format(state.planning?.goals?.totalSaved||0),`de ${money.format(state.planning?.goals?.totalTarget||0)}`)}${metric('Fondo emergencia',money.format(state.planning?.emergencyFund?.currentAmount||0),`meta ${money.format(state.planning?.emergencyFund?.targetAmount||0)}`)}${metric('Cobertura',`${Number(state.planning?.emergencyFund?.coverageMonths||0).toFixed(1)} meses`,'Gasto fijo equivalente')}</div><div class="section-title"><div><h2>Metas y fondos apartados</h2><p>Planea compras, viajes, gastos anuales y reservas sin confundirlos con gasto disponible.</p></div><button class="primary" id="newGoalBtn">+ Meta</button></div><div class="goal-grid">${active.length?active.map(x=>{const g=x.goal;return `<article class="goal-card"><div class="goal-head"><div><div class="goal-kind">${esc(goalTypeLabel(g.type))} · ${esc(g.priority)}</div><h3>${esc(g.name)}</h3></div><span class="quality ${g.status==='completed'?'official':'estimated'}">${g.status==='completed'?'completa':'activa'}</span></div><div class="goal-progress"><div class="goal-amounts"><strong>${money.format(g.currentAmount)}</strong><span>de ${money.format(g.targetAmount)}</span></div><div class="progress"><i style="width:${x.fundedPct}%"></i></div><div class="goal-meta"><span>${x.fundedPct.toFixed(0)}% fondeado</span><span>${g.targetDate?fmtDate(g.targetDate):'sin fecha'}</span></div>${x.requiredMonthly&&x.gap>0?`<div class="goal-required">Aporte aproximado requerido: <strong>${money.format(x.requiredMonthly)}/mes</strong></div>`:''}</div><div class="goal-actions"><button class="primary small" data-goal-contribute="${g.id}" ${g.status==='completed'?'disabled':''}>+ Aportar</button><button class="secondary small danger-text" data-goal-archive="${g.id}">Archivar</button></div></article>`}).join(''):'<section class="panel" style="grid-column:1/-1"><div class="empty-action"><strong>Crea tu primera meta</strong><span>El fondo de emergencia suele ser una buena primera candidata, seguido de compras o gastos anuales previstos.</span><button class="primary" id="emptyNewGoal">+ Crear meta</button></div></section>'}</div><div id="goalEditor"></div>`}
function goalForm(){return `<section class="panel detail"><div class="panel-head"><div><h2>Nueva meta</h2><span>El sistema calcula el aporte mensual necesario si agregas una fecha.</span></div></div><div class="panel-body"><form id="goalForm" class="form-grid"><div class="field"><label>Nombre</label><input id="goalName" placeholder="Ej. Fondo de emergencia" required></div><div class="field"><label>Tipo</label><select id="goalType"><option value="emergency_fund">Fondo de emergencia</option><option value="purchase">Compra</option><option value="travel">Viaje</option><option value="annual_expense">Gasto anual</option><option value="other">Otra</option></select></div><div class="field"><label>Meta</label><input id="goalTarget" type="number" min="1" step="0.01" required></div><div class="field"><label>Ya ahorrado</label><input id="goalCurrent" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Fecha objetivo</label><input id="goalDate" type="date"></div><div class="field"><label>Prioridad</label><select id="goalPriority"><option value="high">Alta</option><option value="medium" selected>Media</option><option value="low">Baja</option></select></div><div class="form-actions"><button class="secondary" type="button" id="cancelGoal">Cancelar</button><button class="primary">Guardar meta</button></div></form></div></section>`}

function renderCards(){
  const cards=state.bootstrap.cards,snaps=snapshotMap(),archived=state.allCards.filter(c=>(c.status||'active')==='archived');
  return `<div class="section-title"><div><h2>Tarjetas activas</h2><p>Puedes agregar nuevas tarjetas o archivar las que dejes de usar sin perder su historial.</p></div><button class="primary" id="newCardBtn">+ Tarjeta</button></div>
  <div class="cards-grid">${cards.map(c=>{const s=snaps.get(c.id),bal=liveBalance(s,c.id),u=bal/c.creditLimit*100,cls=u>=90?'critical':u>=70?'high':'';return `<article class="credit-card"><div data-card-open="${c.id}" class="card-click"><div class="mini-row"><div><div class="bank">${esc(c.issuer)}</div><div class="card-name">${esc(c.name)}</div></div><span class="quality ${s?.dataQuality||'estimated'}">${s?.dataQuality||'estimated'}</span></div><div class="big">${money.format(bal)}</div><div class="muted">saldo de referencia</div><div class="progress ${cls}"><i style="width:${Math.min(100,u)}%"></i></div><div class="cc-foot"><div><span>Utilización</span><strong>${u.toFixed(1)}%</strong></div><div style="text-align:right"><span>Límite</span><strong>${money.format(c.creditLimit)}</strong></div></div></div><div class="card-actions"><button class="secondary small" data-edit-card="${c.id}">Editar</button><button class="secondary small danger-text" data-archive-card="${c.id}">Archivar</button></div></article>`}).join('')}</div>
  ${archived.length?`<section class="panel detail"><div class="panel-head"><div><h2>Tarjetas archivadas</h2><span>Siguen disponibles para reportes históricos</span></div></div><div class="panel-body"><div class="archive-list">${archived.map(c=>`<div class="archive-row"><div><strong>${esc(c.name)}</strong><span>${esc(c.issuer)} · ${money.format(c.creditLimit)}</span></div><button class="secondary small" data-restore-card="${c.id}">Restaurar</button></div>`).join('')}</div></div></section>`:''}<div id="cardDetail"></div><div id="cardEditor"></div>`;
}

async function openCard(id){setRoute('cards');const host=$('#cardDetail');host.innerHTML='<div class="loading">Cargando tarjeta…</div>';try{const d=await api('/cards/'+id),s=d.snapshot;host.innerHTML=`<section class="panel detail"><div class="panel-head"><div><h2>${esc(d.card.name)}</h2><span>Corte día ${d.card.statementCloseDay} · pago personal día ${d.card.personalPayDay||'legal'}</span></div><button class="secondary" id="addForCard">+ Compra</button></div><div class="panel-body"><div class="detail-grid"><div class="detail-kpi"><span>Saldo vivo</span><strong>${money.format(d.currentBalance||0)}</strong></div><div class="detail-kpi"><span>PPNGI</span><strong>${money.format(s?.paymentToAvoidInterest||0)}</strong></div><div class="detail-kpi"><span>Utilización</span><strong>${pct(d.utilization)}</strong></div><div class="detail-kpi"><span>Ciclo capturado</span><strong>${money.format(d.currentCycleSpend)}</strong></div></div>${s?.note?`<div class="note">${esc(s.note)}</div>`:''}<div style="height:16px"></div>${transactionTable(d.transactions)}</div></section>`;$('#addForCard').onclick=()=>{setRoute('transactions');setTimeout(()=>{$('#txCard').value=id;$('#txDescription').focus()},0)};host.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){host.innerHTML=`<div class="note">${esc(e.message)}</div>`}}

function cardForm(card){const c=card||{};const dueType=c.dueRule?.type||'days_after_close';return `<section class="panel detail"><div class="panel-head"><div><h2>${card?'Editar tarjeta':'Agregar tarjeta'}</h2><span>Las reglas de corte determinan a qué mes cae cada compra</span></div></div><div class="panel-body"><form id="cardForm" class="form-grid"><div class="field"><label>Nombre</label><input id="cardName" value="${esc(c.name||'')}" required></div><div class="field"><label>Emisor</label><input id="cardIssuer" value="${esc(c.issuer||'')}" required></div><div class="field"><label>Límite</label><input id="cardLimit" type="number" min="1" step="100" value="${c.creditLimit||''}" required></div><div class="field"><label>Día de corte</label><input id="cardClose" type="number" min="1" max="31" value="${c.statementCloseDay||''}" required></div><div class="field"><label>Regla de vencimiento</label><select id="cardDueType"><option value="days_after_close" ${dueType==='days_after_close'?'selected':''}>Días después del corte</option><option value="fixed_day" ${dueType==='fixed_day'?'selected':''}>Día fijo del mes siguiente</option></select></div><div class="field"><label>Días / día fijo</label><input id="cardDueValue" type="number" min="1" max="60" value="${dueType==='days_after_close'?(c.dueRule?.days||20):(c.dueRule?.day||1)}"></div><div class="field"><label>Día personal de pago</label><input id="cardPayDay" type="number" min="1" max="31" value="${c.personalPayDay||30}"></div><div class="field"><label>APR ordinaria (%)</label><input id="cardApr" type="number" min="0" step="0.01" value="${c.apr?c.apr*100:''}"></div><div class="field"><label>Últimos 4 dígitos</label><input id="cardLast4" maxlength="4" value="${esc(c.last4||'')}"></div><div class="form-actions"><button class="primary" type="submit">${card?'Guardar cambios':'Crear tarjeta'}</button><button type="button" class="secondary" id="cancelCard">Cancelar</button></div></form></div></section>`}

function transactionTable(txs){if(!txs.length)return `<div class="empty"><strong>Sin movimientos capturados</strong>Los estados históricos son la línea base; los nuevos movimientos aparecerán aquí.</div>`;const cards=cardMap();return `<div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Comercio / concepto</th><th>Tarjeta</th><th>Origen</th><th>Tipo</th><th>Monto</th></tr></thead><tbody>${[...txs].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${fmtDate(t.date)}</td><td><strong>${esc(t.description)}</strong><div class="muted">${esc(t.category||'Sin categoría')}</div></td><td>${esc(cards.get(t.cardId)?.name||t.cardId)}</td><td><span class="pill gray">${esc(t.source||'manual')}</span></td><td><span class="pill gray">${esc(t.kind)}</span></td><td><strong>${t.kind==='payment'||t.kind==='refund'?'-':''}${money2.format(t.amount)}</strong></td></tr>`).join('')}</tbody></table></div>`}

function renderTransactions(){const cards=state.bootstrap.cards,txs=state.bootstrap.transactions;return `<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Movimientos</h2><span>${txs.length} registros</span></div></div><div class="panel-body">${transactionTable(txs)}</div></section><section class="panel"><div class="panel-head"><div><h2>Registrar movimiento</h2><span>La app calcula corte y pago</span></div></div><div class="panel-body"><form id="txForm" class="form-grid"><div class="field"><label>Tarjeta</label><select id="txCard" required>${cards.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Fecha</label><input id="txDate" type="date" value="${today()}" required></div><div class="field full"><label>Descripción</label><input id="txDescription" placeholder="Ej. La Comer, Uber, Amazon" required></div><div class="field"><label>Monto</label><input id="txAmount" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Categoría</label><select id="txCategory"><option>Supermercado</option><option>Transporte</option><option>Restaurantes</option><option>Entretenimiento</option><option>Tecnología</option><option>Salud</option><option>Hogar</option><option>Otros</option></select></div><div class="field"><label>Tipo</label><select id="txKind"><option value="purchase">Compra</option><option value="payment">Pago a tarjeta</option><option value="refund">Reembolso</option><option value="subscription">Suscripción</option><option value="fee">Comisión</option><option value="interest">Interés</option><option value="cash_advance">Disposición</option></select></div><div class="field"><label>Financiamiento</label><select id="txFin"><option value="regular">Normal</option><option value="msi">MSI</option><option value="interest_plan">Con interés</option></select></div><div class="field" id="installmentsField" style="display:none"><label>Meses</label><input id="txInstallments" type="number" min="2" max="48" value="6"></div><div class="field" id="aprField" style="display:none"><label>Tasa anual (%)</label><input id="txApr" type="number" min="0" step="0.01" value="36"></div><div class="field full"><div id="projectionBox" class="projection" style="display:none"></div></div><div class="form-actions"><button type="submit" class="primary">Guardar</button></div></form></div></section></div>`}

function renderDebt(){const cards=cardMap();return `<div class="section-title"><div><h2>Deuda que genera intereses</h2><p>Simula abonos extraordinarios antes de mover dinero real.</p></div></div><div class="debt-grid">${state.debts.map(p=>`<article class="debt-card"><div class="debt-title"><div><div class="bank">${esc(cards.get(p.cardId)?.name||p.cardId)}</div><h3>${esc(p.name)}</h3></div><div class="apr">${(p.apr*100).toFixed(1)}% APR</div></div><div class="debt-numbers"><div class="debt-num"><span>Capital</span><strong>${money.format(p.principal)}</strong></div><div class="debt-num"><span>Pago programado</span><strong>${money.format(p.scheduledPayment)}</strong></div><div class="debt-num"><span>Pagos restantes</span><strong>${p.remainingPayments}</strong></div></div><div class="sim-row"><input id="sim-${p.id}" type="number" min="1" step="100" placeholder="Abono extraordinario"><button class="secondary" data-sim="${p.id}">Simular</button></div><div id="sim-result-${p.id}"></div></article>`).join('')}</div>`}

async function loadRecurringMonth(){state.recurringRows=await api('/recurring/month?month='+state.recurringMonth)}
function renderRecurring(){const totalBaseline=state.bootstrap.recurring.reduce((s,r)=>s+monthlyEquivalent(r),0);const periodTotal=state.recurringRows.reduce((s,r)=>s+r.amount,0);return `<div class="section-title"><div><h2>Gastos recurrentes por periodo</h2><p>El monto base sigue intacto. Cada mes/bimestre puede tener su monto real.</p></div><div class="month-picker"><label>Periodo</label><input id="recMonth" type="month" value="${state.recurringMonth}"></div></div><div class="hero-grid">${metric('Base mensual equivalente',money.format(totalBaseline),'Promedio estructural')}${metric('Cargos del periodo',money.format(periodTotal),state.recurringMonth)}${metric('Overrides históricos',String(state.bootstrap.recurringOverrides?.length||0),'Cambios que no alteran otros meses')}${metric('Reglas activas',String(state.bootstrap.recurring.length),'Mensual, bimestral y cada N días')}</div><section class="panel"><div class="panel-head"><div><h2>${state.recurringMonth}</h2><span>Edita sólo este periodo</span></div></div><div class="panel-body"><div class="recurring-grid">${state.recurringRows.map(row=>`<div class="recurring-item ${row.overridden?'overridden':''}"><div><div class="name">${esc(row.recurring.name)} ${row.overridden?'<span class="pill">ajustado</span>':''}</div><div class="freq">${frequencyText(row.recurring)} · base ${money2.format(row.baseAmount)}${row.recurring.offsetIncome?` · apoyo ${money.format(row.recurring.offsetIncome)}`:''}</div></div><div class="rec-edit"><div class="money">${money2.format(row.amount)}<small>${row.amount===0?'sin cargo este periodo':'monto efectivo'}</small></div><button class="secondary small" data-edit-recurring="${row.recurring.id}" data-current="${row.overridden?(row.override?.amount??row.baseAmount):row.baseAmount}">Editar mes</button></div></div>`).join('')}</div></div></section><div id="recEditor"></div>`}

function importStatus(row){return row.status==='matched'?'Coincide':row.status==='possible_match'?'Revisar':row.status==='new'?'Nuevo':row.status==='ignored'?'Ignorado':'Importado'}
function renderImportReview(imp){const unresolved=imp.rows.filter(r=>r.status==='possible_match').length;return `<section class="panel detail"><div class="panel-head"><div><h2>Revisión: ${esc(imp.filename)}</h2><span>${imp.rows.length} movimientos · ${unresolved} requieren decisión</span></div>${imp.status==='review'?`<button class="primary" id="commitImport" ${unresolved?'disabled':''}>Confirmar conciliación</button>`:`<span class="quality">${imp.status}</span>`}</div><div class="panel-body"><div class="detail-grid"><div class="detail-kpi"><span>Corte detectado</span><strong>${imp.summary.statementDate?fmtDate(imp.summary.statementDate):'—'}</strong></div><div class="detail-kpi"><span>Saldo total</span><strong>${imp.summary.totalBalance!=null?money2.format(imp.summary.totalBalance):'—'}</strong></div><div class="detail-kpi"><span>PPNGI</span><strong>${imp.summary.paymentToAvoidInterest!=null?money2.format(imp.summary.paymentToAvoidInterest):'—'}</strong></div><div class="detail-kpi"><span>Calidad</span><strong>${esc(imp.summary.dataQuality)}</strong></div></div>${imp.extractionWarnings.length?`<div class="note">${imp.extractionWarnings.map(esc).join(' ')}</div>`:''}<div style="height:14px"></div><div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Descripción</th><th>Tipo</th><th>Monto</th><th>Match</th><th>Acción</th></tr></thead><tbody>${imp.rows.map(r=>`<tr><td>${fmtDate(r.transactionDate)}</td><td><strong>${esc(r.description)}</strong><div class="muted">${esc(r.financingGuess)}</div></td><td><span class="pill gray">${esc(r.kindGuess)}</span></td><td><strong>${r.sign<0?'-':''}${money2.format(r.amount)}</strong></td><td><span class="quality ${r.status==='possible_match'?'estimated':''}">${importStatus(r)}</span>${r.matchConfidence?`<div class="muted">${Math.round(r.matchConfidence*100)}%</div>`:''}</td><td>${r.status==='possible_match'?`<div class="inline-actions"><button class="secondary tiny" data-import-new="${r.id}">Es nuevo</button><button class="secondary tiny" data-import-ignore="${r.id}">Ignorar</button></div>`:r.status==='new'?`<button class="secondary tiny" data-import-ignore="${r.id}">Ignorar</button>`:''}</td></tr>`).join('')}</tbody></table></div></div></section>`}
function renderImports(){return `<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Importar estado de cuenta</h2><span>PDF con texto o TXT</span></div></div><div class="panel-body"><form id="importForm" class="form-grid"><div class="field"><label>Tarjeta</label><select id="importCard">${state.bootstrap.cards.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Archivo</label><input id="importFile" type="file" accept="application/pdf,text/plain,.pdf,.txt" required></div><div class="field full"><div class="note">El importador extrae movimientos, intenta emparejarlos con lo que ya registraste y no toca el saldo oficial hasta que confirmas la conciliación. Liverpool todavía puede requerir TXT/OCR porque su PDF usa una codificación bastante creativa.</div></div><div class="form-actions"><button class="primary" type="submit">Analizar estado</button></div></form></div></section><section class="panel"><div class="panel-head"><div><h2>Historial de importaciones</h2><span>${state.imports.length} archivos</span></div></div><div class="panel-body"><div class="archive-list">${state.imports.length?state.imports.map(i=>`<button class="import-history" data-open-import="${i.id}"><div><strong>${esc(i.filename)}</strong><span>${esc(cardMap().get(i.cardId)?.name||i.cardId)} · ${fmtDate(i.summary.statementDate)} · ${i.rows.length} movimientos</span></div><span class="quality ${i.status==='review'?'estimated':''}">${i.status}</span></button>`).join(''):'<div class="empty"><strong>Aún no hay estados importados</strong>Sube el siguiente PDF y la máquina hará su ritual burocrático.</div>'}</div></div></section></div><div id="importReview"></div>`}


async function loadForecast(){
  const p=state.preferences||{};
  const effectiveOpening=Number(p.openingCash||0)>0?Number(p.openingCash):Number(state.planning?.liquidAssets||0);const q=new URLSearchParams({asOf:today(),months:String(p.forecastHorizonMonths||12),openingCash:String(effectiveOpening),variable:String(p.variableSpendTarget||0)});
  state.forecast=await api('/forecast?'+q.toString());return state.forecast;
}
function rowClass(n){return n<0?'negative':'positive'}
function renderCashflow(){
  const e=state.forecast,f=e.forecast,m=f.metrics,months=f.monthly,maxOut=Math.max(1,...months.map(x=>x.totalOutflow));
  const upcoming=f.events.slice(0,28);
  return `<div class="hero-grid">${metric('Saldo al final',money.format(m.endingCash),`${f.horizonEnd} · horizonte ${months.length} meses`,rowClass(m.endingCash))}${metric('Mínimo proyectado',money.format(m.minimumCash),m.minimumCashDate?fmtDate(m.minimumCashDate):'Sin caídas bajo saldo inicial',rowClass(m.minimumCash))}${metric('Días bajo cero',String(m.negativeDays),m.firstNegativeDate?`Primero: ${fmtDate(m.firstNegativeDate)}`:'Ninguno',m.negativeDays?'warn':'good')}${metric('Fondo de emergencia',money.format(e.emergencyFund.currentAmount),`${e.emergencyFund.coverageMonths.toFixed(1)} de ${e.emergencyFund.targetMonths} meses`,'')}</div>
  <div class="planning-controls panel"><div class="panel-body"><form id="cashPrefs" class="compact-form"><label>Saldo líquido inicial<input id="cashOpening" type="number" min="0" step="100" value="${f.preferences.openingCash}"></label><label>Gasto variable / mes<input id="cashVariable" type="number" min="0" step="100" value="${f.preferences.variableSpendTarget}"></label><label>Horizonte<select id="cashHorizon">${[3,6,12,18,24].map(x=>`<option value="${x}" ${x===months.length?'selected':''}>${x} meses</option>`).join('')}</select></label><button class="primary">Recalcular y guardar</button></form></div></div>
  ${f.warnings.length?`<div class="forecast-warnings">${f.warnings.map(w=>`<div class="note">${esc(w)}</div>`).join('')}</div>`:''}
  <div class="grid-2 cash-layout"><section class="panel"><div class="panel-head"><div><h2>Flujo mensual</h2><span>Ingresos vs obligaciones conocidas</span></div></div><div class="panel-body"><div class="month-bars">${months.map(x=>`<div class="month-bar"><div class="month-label"><strong>${esc(x.month)}</strong><span class="${rowClass(x.netCashflow)}">${x.netCashflow>=0?'+':''}${money.format(x.netCashflow)}</span></div><div class="bar-track"><i style="width:${Math.max(3,x.totalOutflow/maxOut*100)}%"></i></div><div class="month-detail"><span>Ingreso ${money.format(x.income)}</span><span>Salida ${money.format(x.totalOutflow)}</span><span>Cierre ${money.format(x.endingBalance)}</span></div></div>`).join('')}</div></div></section>
  <section class="panel"><div class="panel-head"><div><h2>Fondo de emergencia</h2><span>Objetivo configurable</span></div></div><div class="panel-body"><div class="emergency-meter"><div class="progress"><i style="width:${Math.min(100,e.emergencyFund.targetAmount?e.emergencyFund.currentAmount/e.emergencyFund.targetAmount*100:0)}%"></i></div><div class="legend-row"><span>Gasto fijo neto estimado</span><strong>${money.format(e.emergencyFund.monthlyEssentialEstimate)}</strong></div><div class="legend-row"><span>Meta ${e.emergencyFund.targetMonths} meses</span><strong>${money.format(e.emergencyFund.targetAmount)}</strong></div><div class="legend-row"><span>Brecha</span><strong>${money.format(e.emergencyFund.gap)}</strong></div></div><div class="note">La meta usa tus gastos recurrentes netos. No pretende adivinar cuánto cuesta una emergencia, porque ni las emergencias tienen la cortesía de respetar presupuestos.</div></div></section></div>
  <div style="height:18px"></div><section class="panel"><div class="panel-head"><div><h2>Desglose mensual</h2><span>Planeación de caja, no contabilidad de devengo</span></div></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>Mes</th><th>Ingresos</th><th>Fijos</th><th>Variable</th><th>Tarjetas</th><th>MSI</th><th>Deuda interés</th><th>Neto</th><th>Saldo</th></tr></thead><tbody>${months.map(x=>`<tr><td><strong>${esc(x.month)}</strong></td><td>${money.format(x.income)}</td><td>${money.format(x.fixedExpenses)}</td><td>${money.format(x.variableBudget)}</td><td>${money.format(x.cardPayments)}</td><td>${money.format(x.installments)}</td><td>${money.format(x.interestDebt)}</td><td class="${rowClass(x.netCashflow)}">${money.format(x.netCashflow)}</td><td class="${rowClass(x.endingBalance)}">${money.format(x.endingBalance)}</td></tr>`).join('')}</tbody></table></div></section>
  <div style="height:18px"></div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Próximos movimientos de caja</h2><span>${upcoming.length} eventos</span></div></div><div class="panel-body"><div class="timeline">${upcoming.map(x=>`<div class="timeline-row"><div class="timeline-date">${fmtDate(x.date)}</div><div class="timeline-name"><strong>${esc(x.label)}</strong><span>${esc(x.itemType||x.type)}${x.assumption?' · estimado':''}</span></div><div class="timeline-amount ${x.type==='income'?'positive':'negative'}">${x.type==='income'?'+':'-'}${money.format(x.amount)}</div></div>`).join('')}</div></div></section>
  <section class="panel"><div class="panel-head"><div><h2>Deuda comprometida conocida</h2><span>Capital con interés + MSI desglosados</span></div></div><div class="panel-body"><div class="timeline">${e.debtTimeline.slice(0,12).map(x=>`<div class="timeline-row"><div class="timeline-date">${esc(x.month)}</div><div class="timeline-name"><strong>${money.format(x.knownCommittedBalance)}</strong><span>Interés ${money.format(x.interestPrincipal)} · MSI ${money.format(x.zeroInterestCommitments)}</span></div><div class="timeline-amount">${money.format(x.scheduledDebtPayments)}</div></div>`).join('')}</div></div></section></div>`;
}
function bindCashflow(){
  $('#cashPrefs').onsubmit=async e=>{e.preventDefault();const patch={openingCash:Number($('#cashOpening').value),variableSpendTarget:Number($('#cashVariable').value),forecastHorizonMonths:Number($('#cashHorizon').value)};state.preferences=await api('/preferences',{method:'PUT',body:JSON.stringify(patch)});await loadForecast();toast('Proyección recalculada');render()};
}
function renderBudgets(){const p=state.preferences,e=state.forecast?.emergencyFund;return `<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Supuestos de planeación</h2><span>Se usan en Cash flow y Simulador</span></div></div><div class="panel-body"><form id="budgetPrefs" class="form-grid"><div class="field"><label>Gasto variable objetivo mensual</label><input id="prefVariable" type="number" min="0" step="100" value="${p.variableSpendTarget}"></div><div class="field"><label>Saldo líquido inicial</label><input id="prefOpening" type="number" min="0" step="100" value="${p.openingCash}"></div><div class="field"><label>Fondo de emergencia actual</label><input id="prefEmergency" type="number" min="0" step="100" value="${p.emergencyFundBalance}"></div><div class="field"><label>Meta de fondo (meses)</label><input id="prefEmergencyMonths" type="number" min="0" max="24" step="0.5" value="${p.emergencyFundMonths}"></div><div class="field"><label>Umbral MSI / ingreso</label><input id="prefMsi" type="number" min="0" max="100" step="1" value="${Math.round(p.maxMsiIncomeRatio*100)}"></div><div class="field"><label>Umbral utilización de crédito</label><input id="prefUtil" type="number" min="0" max="100" step="1" value="${Math.round(p.maxCreditUtilization*100)}"></div><div class="form-actions"><button class="primary">Guardar parámetros</button></div></form></div></section><section class="panel"><div class="panel-head"><div><h2>Lectura actual</h2><span>Las metas no modifican movimientos reales</span></div></div><div class="panel-body">${e?`<div class="detail-grid"><div class="detail-kpi"><span>Meta emergencia</span><strong>${money.format(e.targetAmount)}</strong></div><div class="detail-kpi"><span>Brecha</span><strong>${money.format(e.gap)}</strong></div><div class="detail-kpi"><span>Cobertura</span><strong>${e.coverageMonths.toFixed(1)} meses</strong></div><div class="detail-kpi"><span>Variable</span><strong>${money.format(p.variableSpendTarget)}</strong></div></div>`:''}<div class="note">El gasto variable es un sobre de planeación adicional a tus gastos recurrentes y compromisos de tarjeta. Si gastas menos, la diferencia queda como liquidez; no la convertimos mágicamente en una suscripción nueva.</div></div></section></div>`}
function bindBudgets(){$('#budgetPrefs').onsubmit=async e=>{e.preventDefault();state.preferences=await api('/preferences',{method:'PUT',body:JSON.stringify({variableSpendTarget:Number($('#prefVariable').value),openingCash:Number($('#prefOpening').value),emergencyFundBalance:Number($('#prefEmergency').value),emergencyFundMonths:Number($('#prefEmergencyMonths').value),maxMsiIncomeRatio:Number($('#prefMsi').value)/100,maxCreditUtilization:Number($('#prefUtil').value)/100})});await loadForecast();toast('Parámetros guardados');render()}}
function renderSimulator(){const cards=state.bootstrap.cards,p=state.preferences,debts=state.debts;const r=state.scenario;return `<div class="grid-2 sim-layout"><section class="panel"><div class="panel-head"><div><h2>Construir escenario</h2><span>Todos los campos son opcionales</span></div></div><div class="panel-body"><form id="scenarioForm" class="form-grid"><div class="field"><label>Fecha base</label><input id="scAsOf" type="date" value="${today()}"></div><div class="field"><label>Horizonte</label><select id="scHorizon">${[3,6,12,18,24].map(x=>`<option value="${x}" ${x===p.forecastHorizonMonths?'selected':''}>${x} meses</option>`).join('')}</select></div><div class="field full scenario-head">Abono extraordinario</div><div class="field"><label>Deuda</label><select id="scPlan"><option value="">Ninguna</option>${debts.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></div><div class="field"><label>Monto</label><input id="scExtra" type="number" min="0" step="100" placeholder="0"></div><div class="field"><label>Fecha del abono</label><input id="scExtraDate" type="date" value="${today()}"></div><div class="field full scenario-head">Compra hipotética</div><div class="field"><label>Tarjeta</label><select id="scCard"><option value="">Ninguna</option>${cards.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Monto compra</label><input id="scPurchase" type="number" min="0" step="100" placeholder="0"></div><div class="field"><label>Fecha compra</label><input id="scPurchaseDate" type="date" value="${today()}"></div><div class="field"><label>Financiamiento</label><select id="scFin"><option value="regular">Pago normal</option><option value="msi">MSI</option></select></div><div class="field" id="scMonthsField" style="display:none"><label>Meses</label><input id="scMonths" type="number" min="2" max="48" value="12"></div><div class="field full scenario-head">Ingreso extraordinario</div><div class="field"><label>Monto ingreso</label><input id="scIncome" type="number" min="0" step="100" placeholder="Ej. 18000"></div><div class="field"><label>Fecha ingreso</label><input id="scIncomeDate" type="date" value="${today()}"></div><div class="form-actions"><button class="primary">Simular escenario</button></div></form></div></section><section class="panel"><div class="panel-head"><div><h2>Resultado</h2><span>Baseline vs escenario</span></div></div><div class="panel-body">${r?renderScenarioResult(r):'<div class="empty"><strong>Aún no hay escenario</strong>Prueba un abono a BBVA, una compra a MSI o un ingreso extraordinario.</div>'}</div></section></div>`}
function renderScenarioResult(r){const b=r.baseline.forecast.metrics,s=r.scenario.forecast.metrics,d=r.deltas;return `<div class="scenario-deltas"><div class="detail-kpi"><span>Cambio saldo final</span><strong class="${rowClass(d.endingCash)}">${d.endingCash>=0?'+':''}${money.format(d.endingCash)}</strong></div><div class="detail-kpi"><span>Interés + IVA ahorrado</span><strong class="positive">${money.format(d.interestAndTaxSaved)}</strong></div><div class="detail-kpi"><span>Pagos eliminados</span><strong>${d.paymentsSaved}</strong></div><div class="detail-kpi"><span>Días negativos Δ</span><strong>${d.negativeDays>=0?'+':''}${d.negativeDays}</strong></div></div>${r.alerts.length?`<div class="forecast-warnings">${r.alerts.map(x=>`<div class="note">${esc(x)}</div>`).join('')}</div>`:''}<div class="comparison"><div><span>Baseline final</span><strong>${money.format(b.endingCash)}</strong><small>Mínimo ${money.format(b.minimumCash)}</small></div><div class="arrow">→</div><div><span>Escenario final</span><strong>${money.format(s.endingCash)}</strong><small>Mínimo ${money.format(s.minimumCash)}</small></div></div><div class="mini-forecast">${r.scenario.forecast.monthly.slice(0,8).map((x,i)=>{const base=r.baseline.forecast.monthly[i];return `<div><span>${x.month}</span><strong class="${rowClass(x.endingBalance)}">${money.format(x.endingBalance)}</strong><small>base ${money.format(base?.endingBalance||0)}</small></div>`}).join('')}</div>`}
function bindSimulator(){const fin=$('#scFin');fin.onchange=()=>$('#scMonthsField').style.display=fin.value==='msi'?'flex':'none';$('#scenarioForm').onsubmit=async e=>{e.preventDefault();const body={asOf:$('#scAsOf').value,horizonMonths:Number($('#scHorizon').value),openingCash:Number(state.preferences.openingCash||0)>0?state.preferences.openingCash:Number(state.planning?.liquidAssets||0),variableSpendTarget:state.preferences.variableSpendTarget};const plan=$('#scPlan').value,extra=Number($('#scExtra').value);if(plan&&extra>0)body.extraDebtPayment={planId:plan,date:$('#scExtraDate').value,amount:extra};const card=$('#scCard').value,purchase=Number($('#scPurchase').value);if(card&&purchase>0)body.purchase={cardId:card,date:$('#scPurchaseDate').value,amount:purchase,description:'Compra hipotética',financing:fin.value,installments:fin.value==='msi'?Number($('#scMonths').value):undefined};const inc=Number($('#scIncome').value);if(inc>0)body.oneTimeIncome={date:$('#scIncomeDate').value,amount:inc,label:'Ingreso extraordinario simulado'};state.scenario=await api('/scenarios/simulate',{method:'POST',body:JSON.stringify(body)});toast('Escenario recalculado');render()}}

function aiText(s){let x=esc(s||'');x=x.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');x=x.replace(/^###\s+(.+)$/gm,'<h4>$1</h4>');x=x.replace(/^[-•]\s+(.+)$/gm,'<div class="ai-bullet">• $1</div>');x=x.replace(/\n{2,}/g,'</p><p>').replace(/\n/g,'<br>');return `<p>${x}</p>`}
async function loadCopilot(){
  [state.copilotStatus,state.copilotSessions]=await Promise.all([api('/copilot/status'),api('/copilot/sessions')]);
  if(state.copilotSession){const found=state.copilotSessions.find(s=>s.id===state.copilotSession.id);if(found)state.copilotSession=await api('/copilot/sessions/'+found.id);else state.copilotSession=null;}
  if(!state.copilotSession&&state.copilotSessions.length)state.copilotSession=await api('/copilot/sessions/'+state.copilotSessions[0].id);
}
function copilotPromptButtons(){return ['¿Cómo se ve mi flujo de los próximos 3 meses?','¿Qué deuda me conviene atacar primero y por qué?','¿Cuánto puedo gastar sin caer en saldo negativo?','Compara abonar $10,000 a BBVA vs conservar el efectivo.','¿Cuáles son mis gastos recurrentes de este mes?'];}
function renderToolTrace(m){if(!m.toolTrace?.length)return'';return `<details class="tool-trace"><summary>Datos consultados · ${m.toolTrace.length}</summary>${m.toolTrace.map(t=>`<div class="tool-row"><div><strong>${esc(t.name)}</strong><span>${esc(t.summary)}</span></div><small>${t.durationMs} ms</small></div>`).join('')}</details>`}
function renderCopilot(){const st=state.copilotStatus||{provider:'local',configured:false,model:'—'},session=state.copilotSession,messages=session?.messages||[];return `<div class="copilot-layout"><aside class="panel copilot-side"><div class="panel-head"><div><h2>Conversaciones</h2><span>${state.copilotSessions.length} guardadas localmente</span></div><button class="primary small" id="newCopilot">+ Nueva</button></div><div class="panel-body"><div class="copilot-status ${st.provider}"><div><span class="status-dot"></span><strong>${st.provider==='openai'?'OpenAI conectado':'Modo local'}</strong></div><small>${esc(st.model||'')}</small></div><div class="session-list">${state.copilotSessions.length?state.copilotSessions.map(s=>`<button class="session-item ${session?.id===s.id?'active':''}" data-session-id="${s.id}"><strong>${esc(s.title)}</strong><span>${s.messageCount} mensajes · ${fmtDate(String(s.updatedAt).slice(0,10))}</span></button>`).join(''):'<div class="empty compact"><strong>Sin conversaciones</strong>Crea una para empezar.</div>'}</div>${session?`<button class="secondary danger-text full-btn" id="deleteCopilot">Eliminar conversación</button>`:''}<div class="privacy-box"><strong>Privacidad</strong><span>La clave API nunca llega al navegador. El historial se guarda en tu archivo local de datos. El copiloto es de solo lectura.</span></div></div></aside><section class="panel copilot-main"><div class="panel-head"><div><h2>${session?esc(session.title):'Copiloto financiero'}</h2><span>${st.provider==='openai'?'Razonamiento con herramientas financieras':'Motor local sin API externa'}</span></div><span class="quality ${st.configured?'official':'estimated'}">${st.provider==='openai'?'AI + tools':'local'}</span></div><div class="copilot-chat" id="copilotChat">${messages.length?messages.map(m=>`<article class="chat-msg ${m.role}"><div class="chat-avatar">${m.role==='user'?'AM':'PF'}</div><div class="chat-bubble"><div class="chat-meta">${m.role==='user'?'Tú':`Copiloto · ${esc(m.model||'')}`}</div><div class="chat-text">${aiText(m.content)}</div>${m.warnings?.length?`<div class="chat-warnings">${m.warnings.map(w=>esc(w)).join(' · ')}</div>`:''}${renderToolTrace(m)}</div></article>`).join(''):`<div class="copilot-welcome"><div class="copilot-orb">PF</div><h2>Pregunta sobre tus finanzas</h2><p>Puedo consultar deuda, tarjetas, recurrentes, movimientos, cash flow y ejecutar simulaciones. Los números salen del motor, no de la imaginación del modelo.</p><div class="prompt-grid">${copilotPromptButtons().map(x=>`<button class="prompt-chip" data-copilot-prompt="${esc(x)}">${esc(x)}</button>`).join('')}</div>${!st.configured?'<div class="note">Sin <strong>OPENAI_API_KEY</strong> funciona el modo local. Para conversación flexible, configura la variable de entorno y reinicia la app.</div>':''}</div>`}</div><form id="copilotForm" class="copilot-compose"><textarea id="copilotInput" rows="2" placeholder="Ej. Si abono $8,000 a BBVA el 9 de octubre, ¿cómo cambia mi flujo?" ${state.copilotBusy?'disabled':''}></textarea><button class="primary" ${state.copilotBusy?'disabled':''}>${state.copilotBusy?'Analizando…':'Enviar'}</button></form><div class="copilot-disclaimer">Solo lectura · Las simulaciones no modifican tus movimientos reales.</div></section></div>`}
async function ensureCopilotSession(){if(state.copilotSession)return state.copilotSession;state.copilotSession=await api('/copilot/sessions',{method:'POST'});state.copilotSessions=await api('/copilot/sessions');return state.copilotSession;}
function bindCopilot(){const chat=$('#copilotChat');if(chat)chat.scrollTop=chat.scrollHeight;$('#newCopilot')?.addEventListener('click',async()=>{state.copilotSession=await api('/copilot/sessions',{method:'POST'});state.copilotSessions=await api('/copilot/sessions');render()});$('#deleteCopilot')?.addEventListener('click',async()=>{if(!state.copilotSession||!confirm('¿Eliminar esta conversación del historial local?'))return;await api('/copilot/sessions/'+state.copilotSession.id,{method:'DELETE'});state.copilotSession=null;await loadCopilot();render()});document.querySelectorAll('[data-session-id]').forEach(b=>b.onclick=async()=>{state.copilotSession=await api('/copilot/sessions/'+b.dataset.sessionId);render()});document.querySelectorAll('[data-copilot-prompt]').forEach(b=>b.onclick=async()=>{await sendCopilot(b.dataset.copilotPrompt)});$('#copilotForm')?.addEventListener('submit',async e=>{e.preventDefault();const input=$('#copilotInput');const msg=input.value.trim();if(msg)await sendCopilot(msg)});}
async function sendCopilot(message){if(state.copilotBusy)return;state.copilotBusy=true;try{const session=await ensureCopilotSession();render();const r=await api('/copilot/chat',{method:'POST',body:JSON.stringify({sessionId:session.id,message})});state.copilotSession=await api('/copilot/sessions/'+r.session.id);state.copilotSessions=await api('/copilot/sessions');state.copilotStatus=r.status;toast('Análisis completado');}catch(e){toast(e.message)}finally{state.copilotBusy=false;render()}}

function legacyStatus(item){if(item.imported)return '<span class="quality">importado</span>';if(item.disposition==='candidate')return '<span class="quality estimated">por confirmar</span>';if(item.disposition==='modeled')return '<span class="pill gray">ya modelado</span>';if(item.disposition==='review')return '<span class="quality inconsistent">revisar</span>';return '<span class="pill gray">referencia</span>'}
function renderLegacyRows(items,actions=true){return `<div class="table-wrap"><table class="table"><thead><tr><th>Fuente</th><th>Concepto</th><th>Cuota tracker</th><th>MSI</th><th>Estado</th>${actions?'<th>Acción</th>':''}</tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.source)}</td><td><strong>${esc(i.description)}</strong><div class="muted">${esc(i.note||'')}</div></td><td><strong>${money2.format(i.amount)}</strong>${i.financing==='msi'&&i.transactionAmount?`<div class="muted">principal ${money2.format(i.transactionAmount)}</div>`:''}</td><td>${i.msiCurrent&&i.msiTotal?`${i.msiCurrent}/${i.msiTotal}`:'—'}</td><td>${legacyStatus(i)}</td>${actions?`<td>${i.disposition==='candidate'&&!i.imported?`<button class="secondary tiny touch-action" data-legacy-import="${i.id}">Confirmar</button>`:i.imported?'<span class="muted">Ya está en Movimientos</span>':'—'}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function renderReports(){const r=state.legacyReport;if(!r)return '<div class="loading">Analizando tracker anterior…</div>';const months=Object.entries(r.monthlyTotals),mx=Math.max(...months.map(([,v])=>v),1);const candidates=r.items.filter(i=>i.disposition==='candidate');const sources=Object.entries(r.sourceTotals['2026-10']||{}).sort((a,b)=>b[1]-a[1]);return `<div class="section-title"><div><h2>Tracker anterior integrado</h2><p>Finanzas_Personales_v2 se usa como fuente secundaria de contexto. Nada de aquí afecta saldos hasta que confirmas un movimiento.</p></div><span class="quality estimated">mes-only · derivado</span></div>
<div class="hero-grid">${metric('Plan de octubre',money.format(r.currentCycleTotal),'Obligaciones registradas en el tracker')}${metric('Variable por confirmar',money.format(r.candidateVariableSpend),`${r.candidateCount} movimientos candidatos · meta ${money.format(r.variableSpendTarget)}`,r.variableOverTarget>0?'warn':'good')}${metric('Nuevo MSI detectado',money.format(r.newInstallmentPrincipal),'iPhone · 13 pagos de aprox. $1,958','warn')}${metric('Proyección enero',money.format(r.projectedJanuaryTotal),`${r.declineToJanuaryPct}% menos que octubre`,'good')}</div>
<div class="grid-2" style="margin-top:18px"><section class="panel"><div class="panel-head"><div><h2>Evolución del tracker</h2><span>Oct 2026 → Ene 2027</span></div></div><div class="panel-body"><div class="month-bars">${months.map(([m,v])=>`<div class="month-bar"><div class="month-label"><strong>${esc(m)}</strong><span>${money.format(v)}</span></div><div class="bar-track"><i style="width:${Math.max(4,v/mx*100)}%"></i></div></div>`).join('')}</div><div class="note" style="margin-top:14px">El tracker proyectaba una caída de ${r.declineToJanuaryPct}% en obligaciones entre octubre y enero. La app actual sigue siendo la fuente canónica porque algunos montos antiguos, como renta y mantenimiento, ya fueron actualizados.</div></div></section>
<section class="panel"><div class="panel-head"><div><h2>Lectura financiera</h2><span>Complemento al motor actual</span></div></div><div class="panel-body"><div class="insight-stack"><div class="insight-row"><strong>${money.format(r.knownOctoberInflows)}</strong><span>Ingresos conocidos de octubre al combinar nómina, ingreso extraordinario y apoyo familiar modelado.</span></div><div class="insight-row"><strong class="${r.octoberResidualAfterKnownInflows>=0?'positive':'negative'}">${money.format(r.octoberResidualAfterKnownInflows)}</strong><span>Margen frente al total del tracker antes de partidas no registradas o diferencias de timing.</span></div><div class="insight-row"><strong>${r.bbvaSharePct.toFixed(1)}%</strong><span>del plan de octubre está concentrado en BBVA.</span></div><div class="insight-row"><strong class="${r.variableOverTarget>0?'negative':'positive'}">${r.variableOverTarget>0?'+':''}${money.format(r.variableOverTarget)}</strong><span>contra tu presupuesto variable mensual de ${money.format(r.variableSpendTarget)} (${r.variableOverTargetPct.toFixed(1)}%).</span></div></div></div></section></div>
<section class="panel" style="margin-top:18px"><div class="panel-head"><div><h2>Movimientos del ciclo que faltan por confirmar</h2><span>Se detectaron en el tracker, pero no los sumamos dos veces a ciegas</span></div><span>${candidates.filter(i=>!i.imported).length} pendientes</span></div><div class="panel-body"><div class="note">Las fechas no estaban capturadas en el Excel. Al confirmar un movimiento, la app te pide la fecha real. Para el iPhone, el monto que entra al saldo es el principal completo de ${money.format(r.newInstallmentPrincipal)}, no sólo la mensualidad.</div><div style="height:12px"></div>${renderLegacyRows(candidates,true)}</div></section>
<div class="grid-2" style="margin-top:18px"><section class="panel"><div class="panel-head"><div><h2>Concentración octubre</h2><span>Por fuente de pago</span></div></div><div class="panel-body">${sources.map(([name,val])=>`<div class="mini-row legacy-source"><span>${esc(name)}</span><strong>${money.format(val)}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Qué sí integramos automáticamente</h2><span>Sin alterar tus datos actuales</span></div></div><div class="panel-body"><div class="note">Se añadió al forecast el desglose derivado de Liverpool: Tablet $1,083.17, Xbox $1,744.33, Monitor $588.67 y Playeras $230. Esto cubre el hueco que dejó el PDF de Liverpool, cuya codificación impedía leer los planes.</div><div class="note" style="margin-top:10px">No se sobrescriben tus montos actuales de renta, mantenimiento, suscripciones o recurrentes cuando el Excel antiguo difiere de lo que ya configuraste en la app.</div></div></section></div>
<details class="panel legacy-details" style="margin-top:18px"><summary class="panel-head"><div><h2>Ver las 72 filas del ciclo de octubre</h2><span>Incluye filas ya modeladas, referencias y casos ambiguos</span></div></summary><div class="panel-body">${renderLegacyRows(r.items,false)}</div></details>`}
function bindReports(){document.querySelectorAll('[data-legacy-import]').forEach(b=>b.onclick=async()=>{const item=state.legacyReport.items.find(x=>x.id===b.dataset.legacyImport);if(!item)return;let date=prompt(`Fecha real para ${item.description} (YYYY-MM-DD)`,item.suggestedDate||today());if(!date)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return toast('Usa fecha YYYY-MM-DD');if(item.financing==='msi'&&!confirm(`Esto registrará ${money2.format(item.transactionAmount)} como compra a ${item.installments} MSI. ¿Confirmar?`))return;try{await api(`/reports/legacy-tracker/items/${item.id}/import`,{method:'POST',body:JSON.stringify({date})});await refresh();state.legacyReport=await api('/reports/legacy-tracker');toast('Movimiento integrado al ledger vivo');render()}catch(e){toast(e.message)}});bindDynamic()}

function renderPlaceholder(name,description){return `<div class="placeholder"><h2>${esc(name)}</h2><p>${esc(description)}</p></div>`}
async function render(){const v=$('#view');if(!state.bootstrap)return;if(state.route==='overview'){if(!state.forecast)await loadForecast();v.innerHTML=renderOverview();bindOverview()}else if(state.route==='accounts'){v.innerHTML=renderAccounts();bindAccounts()}else if(state.route==='goals'){v.innerHTML=renderGoals();bindGoals()}else if(state.route==='cards'){v.innerHTML=renderCards();bindCards()}else if(state.route==='transactions'){v.innerHTML=renderTransactions();bindTransactionForm()}else if(state.route==='debt'){v.innerHTML=renderDebt();bindDebt()}else if(state.route==='recurring'){await loadRecurringMonth();v.innerHTML=renderRecurring();bindRecurring()}else if(state.route==='imports'){state.imports=await api('/imports');v.innerHTML=renderImports();bindImports()}else if(state.route==='cashflow'){await loadForecast();v.innerHTML=renderCashflow();bindCashflow()}else if(state.route==='simulator'){v.innerHTML=renderSimulator();bindSimulator()}else if(state.route==='budgets'){if(!state.forecast)await loadForecast();v.innerHTML=renderBudgets();bindBudgets()}else if(state.route==='copilot'){await loadCopilot();v.innerHTML=renderCopilot();bindCopilot()}else if(state.route==='reports'){state.legacyReport=await api('/reports/legacy-tracker');v.innerHTML=renderReports();bindReports()}}

function bindOverview(){bindDynamic();$('#customizeDashboard')?.addEventListener('click',()=>{state.customizing=!state.customizing;render()});$('#cancelCustomize')?.addEventListener('click',async()=>{state.uiPreferences=await api('/ui-preferences');state.customizing=false;applyTheme();render()});document.querySelectorAll('[data-dashboard-preset]').forEach(b=>b.onclick=()=>{const mode=b.dataset.dashboardPreset;state.uiPreferences.dashboardMode=mode;state.uiPreferences.dashboardWidgets=[...(WIDGET_PRESETS[mode]||WIDGET_PRESETS.standard)];render()});$('#saveCustomize')?.addEventListener('click',async()=>{const widgets=[...document.querySelectorAll('[data-widget]:checked')].map(x=>x.dataset.widget);state.uiPreferences=await api('/ui-preferences',{method:'PUT',body:JSON.stringify({dashboardMode:state.uiPreferences.dashboardMode,dashboardWidgets:widgets,theme:state.uiPreferences.theme})});state.customizing=false;toast('Dashboard personalizado');render()});}
function bindAccounts(){const show=()=>{const h=$('#accountEditor');h.innerHTML=accountForm();h.scrollIntoView({behavior:'smooth'});$('#cancelAccount').onclick=()=>h.innerHTML='';$('#accountForm').onsubmit=async e=>{e.preventDefault();await api('/accounts',{method:'POST',body:JSON.stringify({name:$('#accName').value,institution:$('#accInstitution').value,type:$('#accType').value,balance:Number($('#accBalance').value),includeInNetWorth:$('#accNetWorth').checked,isEmergencyFund:$('#accEmergency').checked})});await refresh();toast('Cuenta agregada');render()}};$('#newAccountBtn')?.addEventListener('click',show);$('#emptyNewAccount')?.addEventListener('click',show);document.querySelectorAll('[data-account-balance]').forEach(b=>b.onclick=async()=>{const a=state.accounts.find(x=>x.id===b.dataset.accountBalance);const val=prompt(`Nuevo saldo de ${a?.name||'la cuenta'}`,String(a?.balance??0));if(val===null)return;const n=Number(val);if(!Number.isFinite(n)||n<0)return toast('Saldo inválido');await api('/accounts/'+b.dataset.accountBalance,{method:'PATCH',body:JSON.stringify({balance:n})});await refresh();toast('Saldo actualizado');render()});document.querySelectorAll('[data-account-archive]').forEach(b=>b.onclick=async()=>{if(!confirm('¿Archivar esta cuenta? Dejará de contar en el balance diario.'))return;await api('/accounts/'+b.dataset.accountArchive,{method:'DELETE'});await refresh();toast('Cuenta archivada');render()})}
function bindGoals(){const show=()=>{const h=$('#goalEditor');h.innerHTML=goalForm();h.scrollIntoView({behavior:'smooth'});$('#cancelGoal').onclick=()=>h.innerHTML='';$('#goalForm').onsubmit=async e=>{e.preventDefault();await api('/goals',{method:'POST',body:JSON.stringify({name:$('#goalName').value,type:$('#goalType').value,targetAmount:Number($('#goalTarget').value),currentAmount:Number($('#goalCurrent').value||0),targetDate:$('#goalDate').value||undefined,priority:$('#goalPriority').value})});await refresh();toast('Meta creada');render()}};$('#newGoalBtn')?.addEventListener('click',show);$('#emptyNewGoal')?.addEventListener('click',show);document.querySelectorAll('[data-goal-contribute]').forEach(b=>b.onclick=async()=>{const g=state.goals.find(x=>x.id===b.dataset.goalContribute);const val=prompt(`Aporte a ${g?.name||'la meta'}`,'1000');if(val===null)return;const n=Number(val);if(!(n>0))return toast('Aporte inválido');await api(`/goals/${b.dataset.goalContribute}/contributions`,{method:'POST',body:JSON.stringify({amount:n,date:today()})});await refresh();toast('Aporte registrado');render()});document.querySelectorAll('[data-goal-archive]').forEach(b=>b.onclick=async()=>{if(!confirm('¿Archivar esta meta?'))return;await api('/goals/'+b.dataset.goalArchive,{method:'DELETE'});await refresh();toast('Meta archivada');render()})}
function bindDynamic(){document.querySelectorAll('[data-card-open]').forEach(el=>el.onclick=()=>openCard(el.dataset.cardOpen));document.querySelectorAll('[data-route-jump]').forEach(el=>el.onclick=()=>setRoute(el.dataset.routeJump));document.querySelectorAll('[data-alert-route]').forEach(el=>el.onclick=()=>{const r=el.dataset.alertRoute;if(r)setRoute(r)})}
function bindCards(){
  $('#newCardBtn').onclick=()=>showCardEditor();document.querySelectorAll('[data-edit-card]').forEach(b=>b.onclick=e=>{e.stopPropagation();showCardEditor(state.allCards.find(c=>c.id===b.dataset.editCard))});document.querySelectorAll('[data-archive-card]').forEach(b=>b.onclick=async e=>{e.stopPropagation();if(!confirm('¿Archivar esta tarjeta? Su historial se conservará.'))return;await api('/cards/'+b.dataset.archiveCard,{method:'DELETE'});await refresh();toast('Tarjeta archivada sin borrar su historia');render()});document.querySelectorAll('[data-restore-card]').forEach(b=>b.onclick=async()=>{await api(`/cards/${b.dataset.restoreCard}/restore`,{method:'POST'});await refresh();toast('Tarjeta restaurada');render()});
}
function showCardEditor(card){const host=$('#cardEditor');host.innerHTML=cardForm(card);host.scrollIntoView({behavior:'smooth'});$('#cancelCard').onclick=()=>host.innerHTML='';$('#cardForm').onsubmit=async e=>{e.preventDefault();const type=$('#cardDueType').value,val=Number($('#cardDueValue').value);const payload={name:$('#cardName').value,issuer:$('#cardIssuer').value,creditLimit:Number($('#cardLimit').value),statementCloseDay:Number($('#cardClose').value),dueRule:type==='days_after_close'?{type,days:val}:{type,day:val},personalPayDay:Number($('#cardPayDay').value)||undefined,apr:$('#cardApr').value?Number($('#cardApr').value)/100:undefined,last4:$('#cardLast4').value||undefined};await api(card?'/cards/'+card.id:'/cards',{method:card?'PATCH':'POST',body:JSON.stringify(payload)});await refresh();toast(card?'Tarjeta actualizada':'Tarjeta creada');render()}}

function txPayload(){const fin=$('#txFin')?.value||'regular',kind=$('#txKind')?.value||'purchase';return {cardId:$('#txCard').value,date:$('#txDate').value,description:$('#txDescription').value||'Proyección',amount:Number($('#txAmount').value||0),category:$('#txCategory').value,kind,financing:(kind==='payment'||kind==='refund')?'regular':fin,installments:fin==='msi'&&kind!=='payment'&&kind!=='refund'?Number($('#txInstallments').value):undefined,apr:fin==='interest_plan'?Number($('#txApr').value)/100:undefined}}
function bindTransactionForm(){const fin=$('#txFin'),kind=$('#txKind');const updateFields=()=>{const v=fin.value,transfer=kind.value==='payment'||kind.value==='refund';fin.disabled=transfer;$('#installmentsField').style.display=!transfer&&v==='msi'?'flex':'none';$('#aprField').style.display=!transfer&&v==='interest_plan'?'flex':'none';preview()};fin.onchange=updateFields;kind.onchange=updateFields;['txCard','txDate','txAmount','txInstallments'].forEach(id=>$('#'+id)?.addEventListener('input',preview));$('#txForm').onsubmit=async e=>{e.preventDefault();try{const result=await api('/transactions',{method:'POST',body:JSON.stringify(txPayload())});await refresh();toast((result.transaction.kind==='payment'||result.transaction.kind==='refund')?'Movimiento guardado y saldo recalculado':`Movimiento guardado · pago ${fmtDate(result.projection.payDate)}`);render()}catch(err){toast(err.message)}};updateFields()}
let previewTimer;function preview(){clearTimeout(previewTimer);previewTimer=setTimeout(async()=>{const box=$('#projectionBox');if(!box)return;const p=txPayload();if(p.kind==='payment'||p.kind==='refund'||!p.cardId||!p.date||!(p.amount>0)){box.style.display='none';return}try{const r=await api(`/cards/${p.cardId}/project-purchase`,{method:'POST',body:JSON.stringify(p)});box.style.display='grid';box.innerHTML=`<div><span>Corte</span><strong>${fmtDate(r.close)}</strong></div><div><span>Vencimiento</span><strong>${fmtDate(r.legalDue)}</strong></div><div><span>Pago esperado</span><strong>${fmtDate(r.payDate)}</strong></div>${r.installments?`<div class="schedule">${r.installments.map(i=>`<i>${i.number}/${r.installments.length} · ${esc(i.dueMonth)} · ${money2.format(i.amount)}</i>`).join('')}</div>`:''}`}catch(_){box.style.display='none'}},180)}
function bindDebt(){document.querySelectorAll('[data-sim]').forEach(btn=>btn.onclick=async()=>{const id=btn.dataset.sim,amount=Number($('#sim-'+id).value);if(!(amount>0))return toast('Ingresa un abono mayor a cero');try{const r=await api(`/debt-plans/${id}/simulate-extra-payment`,{method:'POST',body:JSON.stringify({amount})});$('#sim-result-'+id).innerHTML=`<div class="sim-result"><div><span>Interés + IVA ahorrado</span><strong>${money2.format(r.interestAndTaxSaved)}</strong></div><div><span>Pagos eliminados</span><strong>${r.paymentsSaved}</strong></div><div><span>Costo futuro</span><strong>${money2.format(r.after.interestAndTax)}</strong></div></div>`}catch(e){toast(e.message)}})}

function bindRecurring(){$('#recMonth').onchange=async e=>{state.recurringMonth=e.target.value;await render()};document.querySelectorAll('[data-edit-recurring]').forEach(b=>b.onclick=()=>{const id=b.dataset.editRecurring,row=state.recurringRows.find(r=>r.recurring.id===id),host=$('#recEditor');host.innerHTML=`<section class="panel detail"><div class="panel-head"><div><h2>Ajustar ${esc(row.recurring.name)}</h2><span>Sólo ${state.recurringMonth}; los demás meses no cambian</span></div></div><div class="panel-body"><form id="recOverrideForm" class="form-grid"><div class="field"><label>Monto real de este periodo</label><input id="recAmount" type="number" min="0" step="0.01" value="${row.override?.amount??row.baseAmount}" required></div><div class="field"><label>Nota</label><input id="recNote" value="${esc(row.override?.note||'')}" placeholder="Ej. Amazon subió croquetas / recibo CFE alto"></div><div class="form-actions"><button class="primary">Guardar monto del periodo</button><button type="button" class="secondary" id="cancelRec">Cancelar</button></div></form></div></section>`;host.scrollIntoView({behavior:'smooth'});$('#cancelRec').onclick=()=>host.innerHTML='';$('#recOverrideForm').onsubmit=async e=>{e.preventDefault();await api(`/recurring/${id}/overrides/${state.recurringMonth}`,{method:'PUT',body:JSON.stringify({amount:Number($('#recAmount').value),note:$('#recNote').value})});await refresh();toast('Monto de '+state.recurringMonth+' actualizado sin alterar otros periodos');render()}})}

function bindImports(){
  $('#importForm').onsubmit=async e=>{e.preventDefault();const file=$('#importFile').files[0];if(!file)return;const cardId=$('#importCard').value;try{toast('Analizando estado…');const imp=await api(`/imports?cardId=${encodeURIComponent(cardId)}&filename=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'content-type':file.type||'application/octet-stream'},body:file});state.imports=await api('/imports');$('#importReview').innerHTML=renderImportReview(imp);bindImportReview(imp);toast(`${imp.rows.length} movimientos detectados`)}catch(err){toast(err.message)}};
  document.querySelectorAll('[data-open-import]').forEach(b=>b.onclick=async()=>{const imp=await api('/imports/'+b.dataset.openImport);$('#importReview').innerHTML=renderImportReview(imp);bindImportReview(imp);$('#importReview').scrollIntoView({behavior:'smooth'})})
}
function bindImportReview(imp){document.querySelectorAll('[data-import-new]').forEach(b=>b.onclick=()=>resolveImportRow(imp,b.dataset.importNew,'new'));document.querySelectorAll('[data-import-ignore]').forEach(b=>b.onclick=()=>resolveImportRow(imp,b.dataset.importIgnore,'ignore'));const commit=$('#commitImport');if(commit)commit.onclick=async()=>{try{await api(`/imports/${imp.id}/commit`,{method:'POST'});await refresh();state.imports=await api('/imports');toast('Estado conciliado y saldos oficiales actualizados');render()}catch(e){toast(e.message)}}}
async function resolveImportRow(imp,rowId,action){const updated=await api(`/imports/${imp.id}/rows/${rowId}`,{method:'PATCH',body:JSON.stringify({action})});$('#importReview').innerHTML=renderImportReview(updated);bindImportReview(updated)}

document.addEventListener('click',e=>{const b=e.target.closest('.nav-item');if(b)setRoute(b.dataset.route);const m=e.target.closest('[data-mobile-route]');if(m){if(m.dataset.mobileRoute==='more'){const open=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',open);$('#sidebarBackdrop')?.classList.toggle('show',open)}else setRoute(m.dataset.mobileRoute)}});
$('#quickAdd').onclick=()=>{setRoute('transactions');setTimeout(()=>$('#txDescription')?.focus(),30)};
$('#menuBtn').onclick=()=>{const open=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',open);$('#sidebarBackdrop')?.classList.toggle('show',open)};
$('#sidebarBackdrop').onclick=()=>{$('#sidebar').classList.remove('open');$('#sidebarBackdrop').classList.remove('show')};
$('#themeToggle').onclick=async()=>{const current=state.uiPreferences?.theme||'system';const next=current==='system'?'light':current==='light'?'dark':'system';state.uiPreferences=await api('/ui-preferences',{method:'PUT',body:JSON.stringify({...state.uiPreferences,theme:next})});applyTheme();toast(`Tema: ${next==='system'?'sistema':next==='dark'?'oscuro':'claro'}`)};
$('#alertsBtn').onclick=()=>{const p=$('#alertsPopover');p.hidden=!p.hidden};
document.addEventListener('click',e=>{if(!e.target.closest('.popover-wrap'))$('#alertsPopover').hidden=true});
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if((state.uiPreferences?.theme||'system')==='system')applyTheme('system')});
load().catch(e=>{$('#view').innerHTML=`<div class="note">No fue posible iniciar la app: ${esc(e.message)}</div>`});
